// TIGHT COUPLING - OrderService directly creates EmailNotifier
class OrderServiceTight {
    private EmailNotifier notifier = new EmailNotifier(); // hard dependency

    public void placeOrder(Order order) {
        // process order
        notifier.sendEmail(order.getCustomerEmail(), "Order confirmed");
    }
}

// LOOSE COUPLING - OrderService depends on interface
interface NotificationService {
    void notify(String recipient, String message);
}

@Service
class OrderService {
    private final NotificationService notifier; // depends on abstraction

    public OrderService(NotificationService notifier) { // injected by Spring
        this.notifier = notifier;
    }

    public void placeOrder(Order order) {
        // process order
        notifier.notify(order.getCustomerEmail(), "Order confirmed");
    }
}

@Service
class EmailNotifier implements NotificationService {
    public void notify(String recipient, String message) {
        // send email implementation
    }
}

// LOW COHESION - UserService does everything
@Service
class UserServiceLowCohesion {
    public void createUser(User user) { /* save user */ }
    public void sendWelcomeEmail(String email) { /* send email */ }
    public String generateInvoicePdf(Order order) { /* PDF logic */ }
    public double calculateShippingCost(Address addr) { /* shipping */ }
    public void logActivity(String action) { /* logging */ }
    // unrelated responsibilities mixed together
}

// HIGH COHESION - each service has one focused purpose
@Service
class UserService {
    private final UserRepository repository;

    public UserService(UserRepository repository) {
        this.repository = repository;
    }

    public User createUser(User user) {
        validateUser(user); // cohesive: validates user data
        return repository.save(user); // cohesive: persists user
    }

    public Optional<User> findById(Long id) {
        return repository.findById(id); // cohesive: retrieves user
    }

    private void validateUser(User user) { /* validation logic */ }
    // all methods relate to user entity operations
}

@Service
class NotificationService {
    public void sendWelcomeEmail(String email) { /* focused on notifications */ }
}

// TIGHT COUPLING - direct dependency on concrete class
@Service
class OrderServiceTight {
    private StripePaymentGateway paymentGateway = new StripePaymentGateway();

    public void checkout(Order order) {
        paymentGateway.charge(order.getTotal()); // knows Stripe specifics
    }
}

// LOOSE COUPLING - depend on interface abstraction
interface PaymentGateway {
    void processPayment(double amount);
    boolean refund(String transactionId);
}

@Service
class OrderService {
    private final PaymentGateway paymentGateway; // depends on abstraction

    public OrderService(PaymentGateway paymentGateway) { // Spring injects
        this.paymentGateway = paymentGateway;
    }

    public void checkout(Order order) {
        paymentGateway.processPayment(order.getTotal()); // no knowledge of implementation
    }
}

@Service
class StripePaymentGateway implements PaymentGateway {
    public void processPayment(double amount) { /* Stripe API calls */ }
    public boolean refund(String transactionId) { /* Stripe refund logic */ }
}

@Service @Profile("dev")
class MockPaymentGateway implements PaymentGateway {
    public void processPayment(double amount) { /* fake payment for testing */ }
    public boolean refund(String transactionId) { return true; }
}

