// REFACTORED - split into focused services
@Service
class UserService {
    private final UserRepository userRepository;

    public UserService(UserRepository userRepository) {
        this.userRepository = userRepository;
    }

    public User createUser(String name, String email) {
        var user = new User(name, email);
        return userRepository.save(user);
    }
}

@Service
class OrderService {
    private final OrderRepository orderRepository;
    private final TaxCalculator taxCalculator; // low coupling via interface

    public OrderService(OrderRepository orderRepository, TaxCalculator taxCalculator) {
        this.orderRepository = orderRepository;
        this.taxCalculator = taxCalculator;
    }

    public Order processOrder(Long userId, List<Item> items) {
        double subtotal = 0; for (Item it : items) subtotal += it.getPrice();
        double tax = taxCalculator.calculate(subtotal);
        var order = new Order(userId, items, subtotal + tax);
        return orderRepository.save(order);
    }
}
